    grid=both,
    grid style={opacity=0.3},
    width=8cm,
    height=7cm,
    domain=-3:3,
    samples=200,
]
% Hyperbola: -x^2 + 4y^2 = 4 => y = ±sqrt((x^2+4)/4)
\addplot[magenta, thick] ({sqrt(4*x^2 - 4)}, {x});
\addplot[magenta, thick] ({-sqrt(4*x^2 - 4)}, {x});
